fn binary_search(v: &Vec<u64>, k: u64) -> usize {
    let mut left = 0;
    let mut right = v.len() - 1;
    
    while left < right {
        let mid = left + (right - left) / 2;
        if v[mid] < k {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    
    // At this point left == right, and v[left] == k because the target is guaranteed to be present
    left
}